// Python-style exception types.
// The original script lets decode/encode errors propagate uncaught, which
// makes the interpreter print a traceback to stderr and exit with code 1.
// We mirror that contract: these errors carry the Python exception name and
// message, and the entry point turns them into stderr output + exit code 1.

export class PyError extends Error {
  constructor(pyType, message) {
    super(message);
    this.name = 'PyError';
    this.pyType = pyType;
  }
}

export class PyTypeError extends PyError {
  constructor(message) {
    super('TypeError', message);
  }
}

export class PyAssertionError extends PyError {
  constructor(message = '') {
    super('AssertionError', message);
  }
}

export class PyAttributeError extends PyError {
  constructor(message) {
    super('AttributeError', message);
  }
}

export class PyIndexError extends PyError {
  constructor(message) {
    super('IndexError', message);
  }
}

export class PyValueError extends PyError {
  constructor(message) {
    super('ValueError', message);
  }
}

export class PyUnicodeEncodeError extends PyError {
  constructor(message) {
    super('UnicodeEncodeError', message);
  }
}

// Render like the last line of a CPython traceback.
export function formatPyException(err) {
  if (err.message) {
    return `${err.pyType}: ${err.message}`;
  }
  return err.pyType;
}

