// Bencode decoder, behavior-compatible with the Python `bencoder` package
// (observed as a black box through the reference executable).
//
// Data model (all plain JS values, strings hold one byte per char):
//   byte string -> string        (e.g. b'value' -> 'value')
//   integer     -> bigint        (Python ints are arbitrary precision)
//   list        -> Array
//   dict        -> Map           (insertion order, last write wins on dup keys)
//
// Notable quirks reproduced from the reference implementation:
//   - A declared string length larger than the remaining data is clamped,
//     exactly like Python slicing (e.g. '9:value' -> b'value').
//   - Any data left over after the first decoded value is a TypeError
//     ("Malformed input.").
//   - Integers match /^i(-?\d+)e/; a failed match is an AttributeError,
//     an unrecognized leading byte is an AssertionError, and decoding an
//     empty input is an IndexError.

import {
  PyTypeError,
  PyAssertionError,
  PyAttributeError,
  PyIndexError,
  PyValueError,
} from '../pyerrors.mjs';

const INTEGER_RE = /^i(-?\d+)e/;

function isDigit(ch) {
  return ch >= '0' && ch <= '9';
}

function pythonTypeName(value) {
  if (typeof value === 'string') return 'bytes';
  if (typeof value === 'bigint') return 'int';
  if (Array.isArray(value)) return 'list';
  if (value instanceof Map) return 'dict';
  return typeof value;
}

// Returns [decodedValue, remainingInput].
export function decodeFirst(x) {
  const first = x[0];

  if (first === undefined) {
    // Indexing past the end of the byte string.
    throw new PyIndexError('index out of range');
  }

  if (first === 'i') {
    const match = INTEGER_RE.exec(x);
    if (match === null) {
      throw new PyAttributeError("'NoneType' object has no attribute 'group'");
    }
    // BigInt keeps full precision for arbitrarily large integers and
    // normalizes spellings like '-0' or '03' the same way Python int() does.
    return [BigInt(match[1]), x.slice(match[0].length)];
  }

  if (first === 'l') {
    const items = [];
    let rest = x.slice(1);
    while (!rest.startsWith('e')) {
      const [elem, next] = decodeFirst(rest);
      items.push(elem);
      rest = next;
    }
    return [items, rest.slice(1)];
  }

  if (first === 'd') {
    const dict = new Map();
    let rest = x.slice(1);
    while (!rest.startsWith('e')) {
      const [key, afterKey] = decodeFirst(rest);
      const [value, afterValue] = decodeFirst(afterKey);
      if (typeof key !== 'string' && typeof key !== 'bigint') {
        throw new PyTypeError(`unhashable type: '${pythonTypeName(key)}'`);
      }
      dict.set(key, value);
      rest = afterValue;
    }
    return [dict, rest.slice(1)];
  }

  if (isDigit(first)) {
    const colon = x.indexOf(':');
    if (colon === -1) {
      throw new PyValueError('substring not found');
    }
    const length = Number.parseInt(x.slice(0, colon), 10);
    if (Number.isNaN(length)) {
      throw new PyValueError(
        `invalid literal for int() with base 10: '${x.slice(0, colon)}'`,
      );
    }
    const start = colon + 1;
    // slice() clamps the end index, mirroring Python's slicing semantics
    // when the declared length exceeds the available data.
    return [x.slice(start, start + length), x.slice(start + length)];
  }

  throw new PyAssertionError();
}

export function decode(x) {
  const [result, rest] = decodeFirst(x);
  if (rest !== '') {
    throw new PyTypeError('Malformed input.');
  }
  return result;
}

