// Reproduces CPython's repr()/str() rendering for the value model produced
// by the bencode decoder, so that console.log matches Python's print()
// byte for byte.

// repr() of a Python bytes object stored as a one-byte-per-char string.
export function reprBytes(s) {
  // CPython prefers single quotes, switching to double quotes only when the
  // data contains a single quote but no double quote.
  const quote = s.includes("'") && !s.includes('"') ? '"' : "'";
  let out = 'b' + quote;
  for (let i = 0; i < s.length; i++) {
    const ch = s[i];
    const code = s.charCodeAt(i);
    if (ch === quote || ch === '\\') {
      out += '\\' + ch;
    } else if (ch === '\t') {
      out += '\\t';
    } else if (ch === '\n') {
      out += '\\n';
    } else if (ch === '\r') {
      out += '\\r';
    } else if (code >= 0x20 && code < 0x7f) {
      out += ch;
    } else {
      out += '\\x' + code.toString(16).padStart(2, '0');
    }
  }
  return out + quote;
}

// str() of a decoded value, matching print() output of the Python script.
export function pyStr(value) {
  if (typeof value === 'bigint') {
    return value.toString();
  }
  if (typeof value === 'string') {
    return reprBytes(value);
  }
  if (Array.isArray(value)) {
    return '[' + value.map(pyStr).join(', ') + ']';
  }
  if (value instanceof Map) {
    const parts = [];
    for (const [key, val] of value) {
      parts.push(pyStr(key) + ': ' + pyStr(val));
    }
    return '{' + parts.join(', ') + '}';
  }
  throw new TypeError(`cannot render value: ${String(value)}`);
}

