// Minimal re-implementation of the argparse behavior of the source script:
//
//   parser = argparse.ArgumentParser()
//   parser.add_argument('--a', type=str, required=True)
//
// Supported, matching argparse: '--a VALUE', '--a=VALUE', unique prefix
// abbreviations, '-h/--help', '--' separator, exit code 2 with a usage
// message on stderr for any parsing failure.

import { basename } from 'node:path';

const PROG = basename(process.argv[1] || 'test4.mjs');
const USAGE = `usage: ${PROG} [-h] --a A`;
const LONG_OPTIONS = ['--help', '--a'];

function fail(message) {
  process.stderr.write(USAGE + '\n');
  process.stderr.write(`${PROG}: error: ${message}\n`);
  process.exit(2);
}

function printHelp() {
  process.stdout.write(
    USAGE +
      '\n\noptions:\n' +
      '  -h, --help  show this help message and exit\n' +
      '  --a A\n',
  );
  process.exit(0);
}

// argparse's _negative_number_matcher: with no option strings that look
// like negative numbers, tokens like '-3' or '-2.5' are treated as values.
const NEGATIVE_NUMBER_RE = /^-\d+$|^-\d*\.\d+$/;

function looksLikeOption(token) {
  return (
    token.length > 1 && token.startsWith('-') && !NEGATIVE_NUMBER_RE.test(token)
  );
}

function resolveLongOption(name) {
  if (LONG_OPTIONS.includes(name)) return name;
  const candidates = LONG_OPTIONS.filter((opt) => opt.startsWith(name));
  if (candidates.length === 1) return candidates[0];
  if (candidates.length > 1) {
    fail(`ambiguous option: ${name} could match ${candidates.join(', ')}`);
  }
  return null;
}

export function parseArgs(argv) {
  let a;
  let aSeen = false;
  const extras = [];
  let optionsEnded = false;
  let i = 0;

  while (i < argv.length) {
    const token = argv[i];

    if (!optionsEnded && token === '--') {
      optionsEnded = true;
      i += 1;
      continue;
    }

    if (!optionsEnded && token.startsWith('--')) {
      let name = token;
      let inlineValue;
      const eq = token.indexOf('=');
      if (eq !== -1) {
        name = token.slice(0, eq);
        inlineValue = token.slice(eq + 1);
      }
      const option = resolveLongOption(name);
      if (option === null) {
        extras.push(token);
        i += 1;
        continue;
      }
      if (option === '--help') {
        printHelp();
      }
      // option === '--a'
      if (eq !== -1) {
        a = inlineValue;
        aSeen = true;
        i += 1;
        continue;
      }
      const next = argv[i + 1];
      if (next === undefined || looksLikeOption(next)) {
        fail('argument --a: expected one argument');
      }
      a = next;
      aSeen = true;
      i += 2;
      continue;
    }

    if (!optionsEnded && looksLikeOption(token)) {
      if (token === '-h') {
        printHelp();
      }
      extras.push(token);
      i += 1;
      continue;
    }

    extras.push(token);
    i += 1;
  }

  // argparse reports missing required arguments before unrecognized ones.
  if (!aSeen) {
    fail('the following arguments are required: --a');
  }
  if (extras.length > 0) {
    fail(`unrecognized arguments: ${extras.join(' ')}`);
  }

  return { a };
}

