// Equivalent of Python's str.encode('ascii') from the source script.
// The input is kept as a plain string of one-byte characters; anything
// above U+007F raises the same UnicodeEncodeError Python would.

import { PyUnicodeEncodeError } from '../pyerrors.mjs';

export function encodeAscii(s) {
  let start = -1;
  for (let i = 0; i < s.length; i++) {
    if (s.charCodeAt(i) > 0x7f) {
      start = i;
      break;
    }
  }
  if (start !== -1) {
    let end = start;
    while (end + 1 < s.length && s.charCodeAt(end + 1) > 0x7f) {
      end += 1;
    }
    let message;
    if (end === start) {
      const hex = s.charCodeAt(start).toString(16).padStart(2, '0');
      message =
        `'ascii' codec can't encode character '\\x${hex}' ` +
        `in position ${start}: ordinal not in range(128)`;
    } else {
      message =
        `'ascii' codec can't encode characters in position ` +
        `${start}-${end}: ordinal not in range(128)`;
    }
    throw new PyUnicodeEncodeError(message);
  }
  return s;
}

